{{// @category Consequence }}
{{// @tooltip Somewhere Else — death drops the active consequence subject into a different world; the old story ends unfinished. }}
{{// @color #7B2D26 }}
{{// @icon ⚰️ }}
{{// @badge PICK-ONE }}
{{// @mutual-exclusive-group Consequence }}
